int strStr(string h, string nd) {
    int m = nd.size(); if (!m) return 0; vector<int> pi(m, 0);
    for (int i = 1, k = 0; i < m; i++) { while (k && nd[i] != nd[k]) k = pi[k-1]; if (nd[i] == nd[k]) k++; pi[i] = k; }
    for (int i = 0, k = 0; i < (int)h.size(); i++) { while (k && h[i] != nd[k]) k = pi[k-1]; if (h[i] == nd[k]) k++; if (k == m) return i - m + 1; }
    return -1;
}
